head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > syncScrollId]<br/>syncScroll=true 일때 세로 스크롤을 동기화할 GridView 를 설정합니다.",
    "validation" : [
        "세로 스크롤을 동기화할 GridView 의 ID 를 ',' 로 구분하여 한 개 이상 설정합니다.",
        "--- ' ' (Space)가 포함되지 않아야 하며 GridView 컴포넌트만 설정합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }    

    if (typeof target2 !== 'undefined') {
        target2.remove();
    }    

    if (typeof target3 !== 'undefined') {
        target3.remove();
    }    

    // 조건 설정   
    let properties = {        
        syncScroll: true,
        syncScrollId: con_syncScrollId.getText(),
        dataList: "data:dlt_bind",        
    };

    let cList = $c.gcm.createCList(properties);      

    // dataList 생성    
    $c.gcm.createDynamicDataList('', '', 'dlt_bind', '', 10);

    // target 생성
    $c.gcm.createBasicGridView(cList);
    $c.gcm.createBasicGridView('dataList="dlt_bind"', '', 'target2');
    $c.gcm.createBasicGridView('dataList="dlt_bind"', '', 'target3');
}



scwin.btn_syncScroll_onclick = function (e) {
    const targets = ["target1", "target2", "target3"];
    let resultMessage = "";

    targets.forEach(function(targetId) {
        let targetElement = document.querySelector('div[id*="' + targetId + '_scrollY_div"]');

        if (targetElement) {
            let scrollTop = targetElement.scrollTop;
            resultMessage += targetId + " scroll top : " + scrollTop + " / ";
        } else {
            resultMessage += targetId + " 요소 없음 / ";
        }
    });

    wf_body_bottom.getObj("scwin").setReturnValue(resultMessage);
};
